const express = require("express");
const checks = require("./checks");
const ui = require("./ui");
const db = require("./db");

const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(express.json());

// ---- SQLite: the account and its history are saved in database.db ----
db.run("CREATE TABLE IF NOT EXISTS accounts (id INTEGER PRIMARY KEY, name TEXT, balance REAL DEFAULT 0)");
db.run("CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY, account_id INTEGER, text TEXT)");
const bank = { account: null, history: [], msg: "", ok: true };
const saved = db.rows("SELECT name, balance FROM accounts WHERE id = 1");
if (saved.length) {
  bank.account = { name: saved[0].name, balance: Number(saved[0].balance) };
  bank.history = db.rows("SELECT text FROM transactions WHERE account_id = 1 ORDER BY id").map((r) => r.text);
}

function save() {
  const a = bank.account;
  const ops = [["DELETE FROM accounts", []], ["DELETE FROM transactions", []]];
  if (a) {
    ops.push(["INSERT INTO accounts (id, name, balance) VALUES (1, ?, ?)", [String(a.name), Number(a.balance) || 0]]);
    for (const h of bank.history) ops.push(["INSERT INTO transactions (account_id, text) VALUES (1, ?)", [h]]);
  }
  db.many(ops);
}
const money = (x) => String(Math.round(Number(x) * 100) / 100);

app.get("/", (req, res) => {
  const S = checks.loadAll();
  const acc = bank.account;
  const msg = bank.msg ? `<div class="msg ${bank.ok ? "ok" : "bad"}">${bank.msg}</div>` : "";
  let main;
  if (!acc) {
    main = '<div class="card">' + ui.part(S[1]) + msg + '<h2>Open a new account</h2><form method="post" action="/open">' + ui.part(S[2]) +
      (S[3].status === "done" ? "<button>Open account</button>" : "") + "</form>" + (S[3].status !== "done" ? ui.box(S[3]) : "") + "</div>";
  } else {
    const shown = Object.assign({}, acc, { name: ui.esc(acc.name), balance: money(acc.balance) });
    let btns = "";
    if (S[5].status === "done") btns += '<button name="action" value="deposit">Deposit</button>';
    if (S[6].status === "done") btns += '<button class="alt" name="action" value="withdraw">Withdraw</button>';
    const todo = [5, 6, 7, 8].filter((n) => S[n].status !== "done").map((n) => ui.box(S[n])).join("");
    main = '<div class="card">' + ui.part(S[1]) + `<p>Account holder: <b>${shown.name}</b></p>` + ui.part(S[4], shown) + msg +
      '<form method="post" action="/money"><input name="amount" type="number" placeholder="Amount ₹">' + btns + "</form>" + todo +
      (S[10].status === "done" ? '<form method="post" action="/interest"><button class="amber">Add 4% interest</button></form>' : ui.box(S[10])) +
      '<p><a href="/close" style="color:#6b7480">Close account (start again)</a></p></div>';
    if (S[9].status === "done") {
      const items = bank.history.slice().reverse().map((h) => `<li>${ui.esc(h)}</li>`).join("") || '<li style="color:#6b7480">No transactions yet</li>';
      main += '<div class="card"><h2>History</h2><ul>' + items + "</ul></div>";
    } else main += '<div class="card"><h2>History</h2>' + ui.box(S[9]) + "</div>";
  }
  res.send(ui.page("My Bank", S, main));
});

app.post("/open", (req, res) => {
  const S = checks.loadAll();
  const name = String(req.body.name || "").trim() || "Customer";
  if (S[3].status === "done") {
    bank.account = S[3].f(name);
    bank.history = []; bank.ok = true; bank.msg = `Account opened for ${ui.esc(name)} ✅`;
    save();
  }
  res.redirect("/");
});

app.post("/money", (req, res) => {
  const S = checks.loadAll();
  const acc = bank.account;
  const action = req.body.action;
  const amount = Number(req.body.amount) || 0;
  if (!acc || !["deposit", "withdraw"].includes(action)) return res.redirect("/");
  if (S[8].status === "done" && !S[8].f(amount)) { bank.msg = "Enter an amount more than ₹0 ❌"; bank.ok = false; }
  else if (action === "withdraw" && S[7].status === "done" && !S[7].f(acc, amount)) { bank.msg = "Not enough balance ❌"; bank.ok = false; }
  else {
    const step = action === "deposit" ? 5 : 6;
    if (S[step].status === "done") {
      S[step].f(acc, amount);
      const word = action === "deposit" ? "Deposited" : "Withdrew";
      bank.msg = `${word} ₹${money(amount)} ✅`; bank.ok = true;
      if (S[9].status === "done") S[9].f(bank.history, `${word} ₹${money(amount)}`);
      save();
    }
  }
  res.redirect("/");
});

app.post("/interest", (req, res) => {
  const S = checks.loadAll();
  if (bank.account && S[10].status === "done") {
    S[10].f(bank.account);
    bank.msg = "4% interest added ✅"; bank.ok = true;
    if (S[9].status === "done") S[9].f(bank.history, "Interest added (4%)");
    save();
  }
  res.redirect("/");
});

app.get("/close", (req, res) => { Object.assign(bank, { account: null, history: [], msg: "", ok: true }); save(); res.redirect("/"); });

// ==============================================================
//  API: ready-made. Call it with curl: commands/08_api_crud.txt
// ==============================================================
app.get("/api/account", (req, res) => {           // SELECT * FROM accounts WHERE id = 1
  if (!bank.account) return res.status(404).json({ error: "no account yet: open one on the page" });
  res.json({ name: bank.account.name, balance: bank.account.balance, history: bank.history });
});

function apiMove(sign) {
  return (req, res) => {                          // UPDATE accounts SET balance = balance +/- ...
    const a = bank.account;
    const amt = Number((req.body || {}).amount);
    if (!a) return res.status(404).json({ error: "no account yet" });
    if (!(amt > 0)) return res.status(400).json({ error: "amount must be more than 0" });
    if (sign < 0 && amt > a.balance) return res.status(400).json({ error: "not enough balance" });
    a.balance = a.balance + sign * amt;
    bank.history.push(`${sign > 0 ? "Deposited" : "Withdrew"} ₹${money(amt)} (API)`);
    save();
    res.json({ balance: a.balance });
  };
}
app.post("/api/deposit", apiMove(1));
app.post("/api/withdraw", apiMove(-1));

app.listen(3002, () => console.log("\n  👉 Open http://localhost:3002 in your browser.  (Stop: Ctrl + C)\n"));
